import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, ConnectionState, Transport } from './bridge/client';
import { ProjectCard } from './components/ProjectCard';
import { PrinterCard } from './components/PrinterCard';
import type { PrinterActions } from './components/PrinterMenu';
import { PlusGlyph, UploadGlyph } from './components/Glyphs';
import { initialState, reduce } from './state/store';
import { applyAppearance } from './tokens';

// Home is the screen before a project: the gallery takes the width that is
// left, the printer column is a fixed rail. The page draws no top bar -- the
// native shell owns the header above this panel, and a second one here would
// duplicate it.
export function App({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reduce, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onEnvelope: (envelope) => dispatch({ kind: 'envelope', envelope }),
        onConnectionChange: (connection: ConnectionState, detail?: string) =>
          dispatch({ kind: 'connection', state: connection, detail }),
      }),
    [getTransport],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  // Each action clears the last refusal first: its message was about the
  // previous request, not this one.
  const printerActions = useMemo<PrinterActions>(() => {
    const send = (type: 'open_printer_settings' | 'rename_printer' | 'remove_printer' | 'connect_printer', payload: object) => {
      dispatch({ kind: 'printer_action' });
      client.send(type, payload);
    };
    return {
      onConnect: (id) => send('connect_printer', { id }),
      onOpenSettings: (id) => send('open_printer_settings', { id }),
      onRename: (id, name) => send('rename_printer', name === undefined ? { id } : { id, name }),
      onRemove: (id) => send('remove_printer', { id }),
    };
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  if (state.connection !== 'connected' && !state.loaded) {
    return (
      <div className="app connecting">
        <h1>Connecting…</h1>
        <p>Starting Home.</p>
        {state.connectionDetail && (
          <details>
            <summary>Diagnostics</summary>
            <p className="footnote">{state.connectionDetail}</p>
          </details>
        )}
      </div>
    );
  }

  return (
    <div className="app">
      <main className="gallery">
        <header className="gallery-header">
          <span className="section-label">Projects</span>
          <div className="gallery-actions">
            <button type="button" className="button-secondary" onClick={() => client.send('import_project', {})}>
              <UploadGlyph />
              Import
            </button>
            <button type="button" className="button-primary" onClick={() => client.send('new_project', {})}>
              <PlusGlyph />
              New
            </button>
          </div>
        </header>
        {state.projects.length === 0 ? (
          <p className="empty">No projects yet.</p>
        ) : (
          <div className="project-grid">
            {state.projects.map((project) => (
              <ProjectCard
                key={project.id}
                project={project}
                onOpen={(id) => client.send('open_project', { id })}
              />
            ))}
          </div>
        )}
      </main>
      <aside className="printer-column">
        <span className="section-label">Printers</span>
        {state.printerError && (
          <p className="printer-error" role="alert">
            {state.printerError.message}
          </p>
        )}
        {state.printers.map((printer) => (
          <PrinterCard
            key={printer.id}
            printer={printer}
            otherNames={state.printers.filter((other) => other.id !== printer.id).map((other) => other.name)}
            actions={printerActions}
            onLaunchMonitor={(id) => client.send('launch_monitor', { id })}
            highlighted={state.highlightPrinter === printer.name}
          />
        ))}
        <button type="button" className="add-printer" onClick={() => client.send('add_printer', {})}>
          + Add printer
        </button>
      </aside>
    </div>
  );
}
// Home's state and the one reducer that advances it. The page renders what the
// host last said; it owns no project or printer state of its own, so a reload
// is always recoverable from the next `state` envelope.

import type { ConnectionState } from '../bridge/client';
import type {
  Appearance,
  Envelope,
  PrinterErrorPayload,
  PrinterInfo,
  ProjectInfo,
  StatePayload,
} from '../bridge/protocol';

export interface HomeState {
  connection: ConnectionState;
  connectionDetail?: string;
  // Absent until the host answers the handshake with state: an empty gallery
  // and "no projects yet" are different screens.
  loaded: boolean;
  appearance: Appearance;
  projects: ProjectInfo[];
  printers: PrinterInfo[];
  error?: string;
  // The last printer action the host refused. The host follows a refusal with
  // a fresh state, so only the person's next printer action clears it.
  printerError?: PrinterErrorPayload;
  // A printer the conversation just added, which the host leads the column
  // with for this one push; its card draws attention to itself once.
  highlightPrinter?: string;
}

export const initialState: HomeState = {
  connection: 'connecting',
  loaded: false,
  appearance: 'light',
  projects: [],
  printers: [],
};

export type HomeAction =
  | { kind: 'connection'; state: ConnectionState; detail?: string }
  | { kind: 'envelope'; envelope: Envelope }
  | { kind: 'printer_action' };

export function reduce(state: HomeState, action: HomeAction): HomeState {
  if (action.kind === 'connection') {
    return { ...state, connection: action.state, connectionDetail: action.detail };
  }
  if (action.kind === 'printer_action') {
    return { ...state, printerError: undefined };
  }
  const { type, payload } = action.envelope;
  switch (type) {
    case 'state': {
      const next = payload as StatePayload;
      return {
        ...state,
        loaded: true,
        appearance: next.appearance,
        projects: next.projects ?? [],
        printers: next.printers ?? [],
        error: undefined,
        highlightPrinter: next.highlightPrinter || undefined,
      };
    }
    case 'projects':
      return { ...state, projects: (payload as { projects: ProjectInfo[] }).projects ?? [] };
    case 'printers':
      return { ...state, printers: (payload as { printers: PrinterInfo[] }).printers ?? [] };
    case 'appearance':
      return { ...state, appearance: (payload as { appearance: Appearance }).appearance };
    case 'printer_error':
      return { ...state, printerError: payload as PrinterErrorPayload };
    case 'bridge_error':
      return { ...state, error: (payload as { message?: string }).message };
    default:
      return state;
  }
}
import type { PrinterInfo } from '../bridge/protocol';
import { MonitorGlyph, PrinterGlyph } from './Glyphs';
import { PrinterActions, PrinterMenu } from './PrinterMenu';

// A printing printer opens into its job; other printers show their connection
// and a next action so an optional connection can be completed later.
// Giving both states the same green dot made them indistinguishable, so only
// a printing printer's dot is colored. Either way the header row ends in the
// printer's actions menu.
export function PrinterCard({
  printer,
  otherNames,
  actions,
  onLaunchMonitor,
  highlighted,
}: {
  printer: PrinterInfo;
  otherNames: string[];
  actions: PrinterActions;
  onLaunchMonitor: (id: string) => void;
  // The printer a receipt just named: the card's own CSS animation draws
  // attention to it once and ends on its own -- no timer either side manages.
  highlighted?: boolean;
}) {
  const printing = printer.state === 'printing';
  const name = (
    <span className="printer-name-row">
      <PrinterGlyph />
      <span className="printer-name">{printer.name}</span>
    </span>
  );
  // A LAN-only device offers none of the actions; a menu of disabled rows
  // would be a button that does nothing, so it has none.
  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
  const end = (
    <span className="printer-head-end">
      <span className={printing ? 'status-dot printing' : 'status-dot'} aria-hidden="true" />
      {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
    </span>
  );
  const cardClass = (base: string) => (highlighted ? `${base} printer-card-added` : base);
  if (!printing) {
    return (
      <div className={cardClass('printer-card')}>
        <div className="printer-head">{name}{end}</div>
        {printer.connectionText && <div className="printer-detail">{printer.connectionText}</div>}
        {printer.canLaunchMonitor ? (
          <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
            <MonitorGlyph />Launch monitor
          </button>
        ) : printer.connectionAction === 'reconnect' && actions.onConnect && (
          <button type="button" className="button-secondary launch-monitor" onClick={() => actions.onConnect?.(printer.id)}>Reconnect</button>
        )}
      </div>
    );
  }
  return (
    <div className={cardClass('printer-card')}>
      <div className="printer-head">
        {name}
        {end}
      </div>
      {printer.statusText && <div className="printer-job">{printer.statusText}</div>}
      {printer.progressPercent !== undefined && (
        <div
          className="printer-progress"
          role="progressbar"
          aria-valuenow={Math.round(printer.progressPercent)}
          aria-valuemin={0}
          aria-valuemax={100}
        >
          <span style={{ width: `${Math.max(0, Math.min(100, printer.progressPercent))}%` }} />
        </div>
      )}
      {printer.connectionText && <div className="printer-detail">{printer.connectionText}</div>}
      {printer.nozzleText && <div className="printer-detail">{printer.nozzleText}</div>}
      {printer.spools.length > 0 && (
        <div className="printer-spools">
          {printer.materialLabel && <span className="printer-material">{printer.materialLabel}</span>}
          {printer.spools.map((spool, index) => (
            // The border is what keeps a black spool visible on the dark card
            // and a white one on the light card.
            <span
              key={`${spool.colour}-${index}`}
              className="spool-swatch"
              style={{ background: spool.colour }}
            />
          ))}
        </div>
      )}
      {printer.canLaunchMonitor && (
        <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
          <MonitorGlyph />
          Launch monitor
        </button>
      )}
    </div>
  );
}
