// The first system filament preset of `type`, for a remembered spool.
static std::string system_filament(const std::string& type)
{
    for (const Preset& preset : wxGetApp().preset_bundle->filaments)
        if (preset.is_system && preset.is_visible) {
            const auto* types = preset.config.option<ConfigOptionStrings>("filament_type");
            if (types != nullptr && !types->values.empty() && types->values.front() == type)
                return preset.name;
        }
    return {};
}

bool add_live_printer(const std::string& model_id, const std::string& name)
{
    const auto& candidates = m_live_catalog.candidates();
    const auto  found      = std::find_if(candidates.begin(), candidates.end(), [&](const auto& candidate) {
        return candidate.model_id == model_id && candidate.variant == "0.4";
    });
    check(found != candidates.end(), "live_catalog_has_" + name);
    if (found == candidates.end())
        return false;
    PrinterSetup::AddPrinterRequest request;
    request.vendor_id = found->vendor_id;
    request.model_id  = found->model_id;
    request.variant   = found->variant;
    request.material  = found->default_material;
    request.name      = name;
    PrinterSetup::SavedPrinter saved;
    const std::string problem = m_live_backend->add_printer(request, saved);
    check(problem.empty() && saved.name == name, "live_added_" + name);
    return problem.empty();
}

void write_live_control(const std::string& json)
{
    boost::filesystem::create_directories(boost::filesystem::path(m_live_control).parent_path());
    boost::nowide::ofstream out(m_live_control);
    out << json;
}

// Home as a person sees it on the way in, then handed to the capture.
void live_shot(const std::string& name, std::function<void()> then)
{
    m_frame->select_tab(size_t(MainFrame::tpHome));
    installed_shell()->home_view()->refresh();
    wait_until_settled("live_" + name + "_settled", [self = shared_from_this(), name, then] {
        std::cerr << "HARNESS SHOT " << name << " READY" << std::endl;
        const fs::path done = self->m_state->capture_dir / (name + ".done");
        self->wait_until([done] { return fs::exists(done); }, "live_" + name + "_captured", [self, name, then] {
            // Where the capture's clicks, if any, left the app.
            std::cerr << "HARNESS NOTE live_" << name << "_after tab=" << self->m_notebook->GetSelection()
                      << " printer_windows=" << printer_windows().size()
                      << " selected_printer=" << self->selected_printer() << std::endl;
            self->m_frame->select_tab(size_t(MainFrame::tpHome));
            then();
        });
    });
}

void begin_home_printers_live()
{
    using namespace std::chrono_literals;
    fs::create_directories(m_state->capture_dir);
    wxGetApp().app_config->set("jusprin", "fake_printer", "true");
    Workspace::SpoolStore* spools = installed_shell()->status_row()->spool_store();
    m_live_catalog = PrinterSetup::PrinterCatalog::load(Slic3r::resources_dir());
    m_live_backend = std::make_shared<PrinterSetup::OrcaPrinterBackend>(
        *m_plater, PrinterSetup::PrinterCatalog::load(Slic3r::resources_dir()), spools);

    // Finding 04: a host whose test fails, then Home.
    if (!add_live_printer("Creality K1", kLiveNever) || !add_live_printer("Voron 2.4 350", kLiveHost) ||
        !add_live_printer("Bambu Lab A1 mini", kLiveBambu)) {
        finish();
        return;
    }
    check(connect_host_and_wait(*m_live_backend, kLiveNever, "http://127.0.0.1:1", 20s).state == "failed",
          "live_never_host_test_fails");
    check(connect_host_and_wait(*m_live_backend, kLiveHost, "http://127.0.0.1:7125", 20s).state == "verified",
          "live_host_connects_to_the_stand_in");
    // Remembered spools: a colour and a material only on the host, a
    // material only on the printer that never connected.
    if (spools != nullptr) {
        const auto remember = [spools](const std::string& printer, const std::string& type, const std::string& colour,
                                       const std::string& name) {
            Workspace::Spool spool;
            spool.printer_preset  = printer;
            spool.filament_preset = system_filament(type);
            spool.colour          = colour;
            spool.name            = name;
            spools->add(std::move(spool));
        };
        remember(kLiveHost, "ABS", "#2E6FD8", "Blue ABS");
        remember(kLiveHost, "PETG", "", "PETG, colour not noted");
        remember(kLiveNever, "PLA", "", "PLA");
    }

    m_live_backend->prepare_connection(kLiveBambu);
    wait_until([self = shared_from_this()] { return !self->m_live_backend->connection(kLiveBambu).candidates.empty(); },
               "live_fake_discovered", [self = shared_from_this()] {
                   const std::string device = self->m_live_backend->connection(kLiveBambu).candidates.front().id;
                   const auto fake = std::dynamic_pointer_cast<FakeBambuAgent>(wxGetApp().getAgent()->get_printer_agent());
                   self->check(fake != nullptr, "live_fake_agent_installed");
                   if (fake == nullptr) {
                       self->finish();
                       return;
                   }
                   self->m_live_control = fake->control_file_path();
                   self->write_live_control(self->live_trays(R"("state":"idle")"));
                   self->check(Printers::link_named_printer(kLiveBambu, device).empty() &&
                                   self->m_live_backend->connect_printer(kLiveBambu, device, "").empty(),
                               "live_bambu_connect_starts");
                   self->wait_until(
                       [self] {
                           const auto card = self->home_card(kLiveBambu);
                           return self->m_live_backend->connection(kLiveBambu).state == "verified" && card &&
                                  card->spools.size() == 3;
                       },
                       "live_bambu_online_with_trays", [self] { self->live_idle(); });
               });
}

// The fake's control file with three trays: two coloured PLAs and a PETG
// that reports no colour.
static std::string live_trays(const std::string& state)
{
    return "{" + state +
           R"(,"spools":[{"subBrands":"PLA Matte","trayType":"PLA","colour":"5F7D4FFF"},)"
           R"({"subBrands":"PLA Basic","trayType":"PLA","colour":"C8202DFF"},)"
           R"({"subBrands":"PETG HF","trayType":"PETG"}]})";
}

void live_idle()
{
    live_shot("1-idle", [self = shared_from_this()] {
        // The tester clicks "Launch monitor" on the Bambu card.
        self->live_shot("2-launch-monitor", [self] { self->live_printing(); });
    });
}

void live_printing()
{
    write_live_control(live_trays(R"("state":"printing","progress":0.43)"));
    wait_until(
        [self = shared_from_this()] {
            const auto card = self->home_card(kLiveBambu);
            return card && card->state == Home::PrinterState::Printing && card->progress_percent == 43;
        },
        "live_bambu_printing", [self = shared_from_this()] { self->live_shot("3-printing", [self] { self->live_offline(); }); });
}

void live_offline()
{
    write_live_control(live_trays(R"("state":"idle","offline":true)"));
    wait_until(
        [self = shared_from_this()] {
            const auto card = self->home_card(kLiveBambu);
            return card && card->connection_state == Home::ConnectionState::Offline;
